def semver_sort(versions):
    def parse_version(version):
        # Split by '+' to remove build metadata
        version_without_build = version.split('+')[0]

        # Split by '-' to separate core version from pre-release
        if '-' in version_without_build:
            core_part, prerelease_part = version_without_build.split('-', 1)
        else:
            core_part = version_without_build
            prerelease_part = None

        # Parse MAJOR.MINOR.PATCH
        major, minor, patch = map(int, core_part.split('.'))

        # Parse pre-release identifiers
        if prerelease_part:
            prerelease_identifiers = prerelease_part.split('.')
        else:
            prerelease_identifiers = None

        return (major, minor, patch, prerelease_identifiers)

    def prerelease_sort_key(identifiers):
        if identifiers is None:
            # No pre-release sorts after pre-release
            return (1,)

        # Pre-release sorts before no pre-release
        result = (0,)
        for identifier in identifiers:
            if identifier.isdigit():
                # All-digit sorts numerically and before non-digit
                result += ((0, int(identifier)),)
            else:
                # Non-digit sorts by ASCII after all-digit
                result += ((1, identifier),)
        return result

    def sort_key(item):
        index, version = item
        major, minor, patch, prerelease_identifiers = parse_version(version)
        return (major, minor, patch, prerelease_sort_key(prerelease_identifiers), index)

    indexed_versions = list(enumerate(versions))
    sorted_versions = sorted(indexed_versions, key=sort_key)
    return [version for _, version in sorted_versions]

